@using sv_f67717bcb188462f8a98fb3da4d105ac.Models

<nav class="mb-4">
    <div class="d-flex justify-content-between align-items-center position-relative">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;
            var isFuture = !isCompleted && !isCurrent;

            <div class="text-center flex-fill" style="z-index: 1;">
                <button type="button"
                        class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepButtonClass(isCompleted, isCurrent)"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@isFuture"
                        @onclick="() => OnStepClicked.InvokeAsync(step)">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold" : "")">
                    @StepNames[step]
                </div>
            </div>
        }
    </div>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static string StepButtonClass(bool completed, bool current) =>
        current ? "btn-primary" : completed ? "btn-success" : "btn-outline-secondary";
}

