@using sv_f67717bcb188462f8a98fb3da4d105ac.Models

<h4 class="mb-3">References</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Model.References.Count; i++)
{
    var index = i;
    <ReferenceForm Reference="Model.References[index]"
                   ReferenceNumber="@(index + 1)"
                   CanRemove="@(Model.References.Count > 2)"
                   OnRemove="() => RemoveReference(index)" />
}

@if (Model.References.Count < 3)
{
    <button type="button" class="btn btn-outline-primary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (Model.References.Count < 3)
            Model.References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (Model.References.Count > 2)
            Model.References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in Model.References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference must have at least a name and email.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

